insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000099101', '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000263', 'multiple_choice', 'easy', 'published', 'Ao revisar um cálculo no quadro, Examine \int_1^{\infty}\frac{1}{x^2}\,dx. Qual opção descreve corretamente a estratégia e a conclusão?') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
