insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000099106', 'Converge e vale $\frac{1}{1}$.', 'A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Como $p=2>1$, trata-se de uma integral de potência convergente. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
