insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000099116', 'Converge e vale $2$.', 'A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. A descontinuidade está em $x=0$; como o expoente $1/2$ é menor que $1$, o limite existe. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
