insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000099150', 'É decrescente, limitada inferiormente por $2$ e converge para $2$.', 'A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. A parcela $1/(n+8)$ diminui e permanece positiva quando $n$ cresce. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000991501', '40000000-0000-4000-8000-000000099150', 'Leia o objetivo', 'Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.', 1), ('70000000-0000-4000-8000-000000991502', '40000000-0000-4000-8000-000000099150', 'Reconheça a ideia', 'A parcela $1/(n+8)$ diminui e permanece positiva quando $n$ cresce.', 2), ('70000000-0000-4000-8000-000000991503', '40000000-0000-4000-8000-000000099150', 'Escreva a relação', 'Registre a definição, fórmula ou teste que se aplica antes de simplificar.', 3), ('70000000-0000-4000-8000-000000991504', '40000000-0000-4000-8000-000000099150', 'Desenvolva a análise', 'Execute a transformação necessária e obtenha: É decrescente, limitada inferiormente por $2$ e converge para $2$.', 4), ('70000000-0000-4000-8000-000000991505', '40000000-0000-4000-8000-000000099150', 'Confira a conclusão', 'Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
